最简单粗暴的方法，📼只调这个让气泡框变小，也会带动所有气泡元素变小，记得改间缝。
代码成分很杂，是属于拼拼乐，除去一半自己肘的代码以外，其他代码有参考借用类名和使用了拼好码and一些小伙伴的代码。

不要二传商用。
by：阿遥/Lyo——*/


/*字体-没加，不过更推荐宋体这一类看起来很舒适的字体吧*/
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {

    font-family: "KingHwaOldSong";

    font-weight: normal;

    /* font-feature-settings: "hwid"; 启用等宽变化字形 */

}

/*顶栏*/
#top-bar {
    position: fixed;
    pointer-events: none;
    z-index: 99;
    background: none;
    border: 0;
    background-color: rgba(0, 0, 0, 0) !important;
    box-shadow: none;
    overflow: visible;
    width: auto;
    height: auto;
    left: 0;
    right: auto;
}

#top-bar::before {
    content: '';
    position: absolute;
    top: 1px;
    left: 0;
    right: auto;
    bottom: auto;
    width: 100%;
    height: 100%;
    background-image: url('https://iili.io/qFIDLrX.png');
    background-size: auto;
    background-repeat: no-repeat;
    background-position: left top;
    border: 0px solid rgba(242, 239, 234, 0);
    border-radius: 0px;
    z-index: 9;
}

@media screen and (max-width: 9999px) {
    #top-bar {
        width: 100vw;
        height: auto;
        overflow: visible !important;
    }

    #top-bar::before {
        min-width: 100%;
        min-height: 100px;
        background-size: contain;
        background-position: center top;
    }
}


/*顶栏小装饰*/
#top-bar::after {
    content: '';
    position: absolute;
    bottom: -450px; 
    left: 93.5%;
    transform: translateX(-50%);
    width: 150px; /* 装饰宽度 */
    height: 150px; /* 装饰高度 */
    background-image: url(''); 
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 10000;
    pointer-events: none;
}


/*图标*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}

#top-settings-holder .drawer {
    flex: 1; 
}

/* 图标代码 */
#top-settings-holder .drawer-icon {
    display: block; 
    margin: 0 auto;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 28px; /* 图标宽度 */
    height: 28px; /* 图标高度 */
    opacity: 0 !important;
}

#top-settings-holder:hover .drawer-icon,#table_drawer_icon::before {
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover {
    transform: scale(1.4); 
    opacity: 1 !important; 
}


/* AI响应配置 */
.drawer-icon.fa-sliders {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* API连接 */
.drawer-icon.fa-plug {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* AI回复格式化 */
.drawer-icon.fa-font {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* 世界书信息 */
.drawer-icon.fa-book-atlas {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* 美化主题设置 */
#user-settings-button .drawer-icon {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* 背景图 */
#backgrounds-drawer-toggle .drawer-icon,
#logo_block .drawer-icon {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

 /* 扩展 */
.drawer-icon.fa-cubes {
   background-image: url('https://iili.io/qFIbkn2.png');
}

/* 记忆表格 */
.drawer-icon.fa-bars-progress,#table_drawer_icon::before {
    visibility: visible !important;
    display: block !important;
    opacity: 1 !important;
    background-image: url('https://iili.io/qFIbkn2.png') !important; 
}

/* 用户角色管理 */
.drawer-icon.fa-face-smile {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}

/* 角色卡 */
.drawer-icon.fa-address-card {
   background-image: url('https://iili.io/qFIbkn2.png'); 
}


/* 隐藏滚动条 */
::-webkit-scrollbar {
    display: none;
}



/* 1.气泡层 */
.mes {
  position: relative;
  z-index: -2;
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  max-width: 400px;/*💽气泡层大小，也就是适配手机的尺寸大小，自己尝试适配多少px*/
  width:100%;
  margin: 180px auto 80px !important; /*💽历史和最新消息的间缝大小*/
  background-size: 400px auto; /*💿这里同样改尺寸大小，以防万一*/
  padding-top: 10px !important; 
  padding-bottom: 30px !important; 
  transform: scale(1) rotate(0deg) !important;
  background-image: url('https://iili.io/qFIpbpa.png'); 
  background-repeat: repeat-y;
  background-position: top center;
  overflow: visible;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important; 
}

/*上层装饰层 */
.mes::after {
  content: '';
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 400px !important ;/*💽装饰层尺寸大小，解释和上面气泡层尺寸一样*/
  max-width: none !important;
  height: 220px;
  background-image: url('https://iili.io/qFImZbf.png');
  background-size: 100% auto; 
  background-repeat: no-repeat;
  background-position: center top;
  pointer-events: none;
  z-index: -1;
  top: -142px !important; /*💽上下*/
}

/*下层装饰层-没做*/
.mes::before {
  content: "";
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 400px !important; /* 💽装饰层尺寸 */
  max-width: none !important;
  height: 220px;
  background-image: url('https://iili.io/qFIyJBp.png');
  background-repeat: no-repeat;
  background-size: 100% auto; 
  background-position: center bottom;
  z-index: -1;
  pointer-events: none;
  bottom: -100px !important;  /*💽上下*/
}


/* ========头像与头像框========= */
/* 头像容器位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: -100px !important;    /* 💽上下微调 */
    left: 72% !important;   /* 💽左右微调 */
    transform: translateX(-50%) !important;
    width: auto !important;
    height: auto !important;
    padding: 0 !important;
    margin: 0 !important;
    z-index: 1 !important;
    overflow: visible !important;
    filter: none !important;
    box-shadow: none !important;
}

/* 头像本体 */
.mesAvatarWrapper .avatar {
    width: 100px;  
    height: 100px;
    transform: scale(1.85) rotate(0deg) !important; /* 💽缩放与旋转 */
    transform-origin: center center !important;
    max-width: unset !important;
    max-height: unset !important;
    clip-path: polygon(26% 20%, 100% 20%, 100% 65%, 0 65%, 0 28%);
}

.mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    box-shadow: none !important;
}

/* 头像框 */
.mesAvatarWrapper::after {
    content: '';
    position: absolute;
    top:40% !important;   /* 💽上下 */
    left: 32% !important;  /* 💽左右 */
    width: 100% !important;
    height: 100% !important;
    transform: translate(-50%, -50%) scale(2.5) rotate(0deg) !important; 
    background-image: url('https://iili.io/qFT9RPp.png');
    background-size: contain !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    pointer-events: none;
    z-index: 1;
}

/* .2.名字与时间戳 */
/*必要的前置*/
.mes_block {
    position: relative !important;
    overflow: visible !important; 
    margin-top: 0px; 
    z-index: auto;
}

/* 💽名字 */
.name_text {
    position: absolute !important;
    z-index: 10;
    top: -65px !important;      /* 💽上下微调 */
    left: 39% !important;       
    transform: translate(-50%,-50%) rotate(0deg) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 10.5px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    color: #999 !important; /* 颜色 */
    opacity: 1 !important;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
    pointer-events: none;
}


.name_text::before {
    content: 'ଘ'; 
    display: inline-block;
    margin-right: 2px;
    color: inherit;
    pointer-events: none;
}

.name_text::after {
    content: 'ଓ'; 
    display: inline-block;
    margin-left: 2px;
    pointer-events: none;
}


/* 💽时间戳 */
.timestamp {
    position: absolute !important;
    z-index: 10;
    top: -65px !important;      /* 💽上下微调 */
    left: 39% !important;       
    transform: translate(-50%,-50%) rotate(0deg) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 11px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    color: #999 !important; /* 颜色 */
    opacity: 1 !important;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
    pointer-events: none;
}

.timestamp::before {
    content: '';
    display: inline-block;
    margin-right: 0px;
}

.timestamp::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 3. 三元素信息 (楼层、计时、词符) */
/* 楼层数 */
.mesIDDisplay {
    position: absolute !important;
    z-index: 10;
    top: -5px !important;      /* 💽上下微调 */
    left: -195% !important;       
    transform: translateX(-50%) rotate(0deg) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 10px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    color: #999 !important; /* 颜色 */
    opacity: 1 !important;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
    pointer-events: none;
}

.mesIDDisplay::before {
    content: ''; 
    display: inline-block;
    margin-right: -5px;
}

.mesIDDisplay::after {
    content: ''; 
    display: inline-block;
    margin-left: 5px;
}

/* 回复计时 */
.mes_timer {
    position: absolute !important;
    z-index: 10;
    top: 57px !important;      /* 💽上下微调 */
    left: -105% !important;       
    transform: translateX(-50%) rotate(0deg) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 10px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    color: #999 !important; /* 颜色 */
    opacity: 1 !important;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
    pointer-events: none;
}

.mes_timer::before {
    content: '记录'; 
    display: inline-block;
    margin-right: 2px;
}

.mes_timer::after {
    content: '';
    display: inline-block;
    margin-left: 2px;
}

/* 词符数 */
.tokenCounterDisplay {
    position: absolute !important;
    z-index: 9;
    top: -10px !important;     /* 💽上下微调 */
    left: 145px !important;    /* 💽左右微调 */
    transform: translateX(-50%) rotate(0deg);
    font-size: 10px !important;
    font-weight: 300 !important;
    color: #fff !important; 
    -webkit-text-stroke: 0.5px #ffffff !important;
    paint-order: stroke fill !important;
    white-space: nowrap;
    opacity: 1;
}

.tokenCounterDisplay::before {
    content: '';
    display: inline-block;
    margin-right: 0px;
}

.tokenCounterDisplay::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 4. 操作按钮 (小铅笔、复制等 - 平时状态) */
.mes_buttons {
    position: absolute !important;
    z-index: 9;
    top: -5px !important;      /* 💽上下位置 */
    right: 25px !important;    /* 💽左右位置 */
    display: flex;             
    flex-direction: row;       
    align-items: center;
    margin: 0 !important;
    padding: 0 !important;
    opacity: 1 !important;         
}

.mes[typing="true"] .mes_buttons {
    display: none !important;
    opacity: 0 !important;
    pointer-events: none !important;
}

.mes_buttons > div,
.mes_buttons button {
    opacity: 1 !important;
    visibility: visible !important;
}

.mes_buttons[style*="display: none"],
.mes_buttons[style*="display:none"] {
    display: none !important;
    opacity: 1 !important;
}


/* 编辑状态菜单 */
.mes_edit_buttons {
    position: absolute !important;
    z-index: 15;
    top: -15px !important;      
    right: 40px !important;
    flex-direction: row;
    align-items: center;
    gap: 0px;        
    opacity: 1 !important; 
    display: none; 
}

/* 去除编辑、删除、重生成等按钮的阴影和发光 */
.mes_buttons div, 
.mes_edit,
.mes_text_paste {
    text-shadow: none !important;  
    box-shadow: none !important;   
    filter: none !important;       
}

.mes_buttons div:hover,
.mes_edit:hover {
    text-shadow: none !important;
}


.mes_buttons,
.mes .mes_buttons,
.mes:hover .mes_buttons {
    opacity: 1 !important;
}

/* -5. 文本框主体 (Text)- */
.mes_text {
    position: relative !important;
    z-index: 2 !important; 
}

/* --- User (用户) 文本框 --- */
.mes[is_user="true"] .mes_text {
    padding-top: 5px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: 5px !important;/*💿同上*/
    padding-bottom: 0px !important; /* 💽底部留白 */
    padding-left: 15px !important;   /* 💽左侧留白 */
    padding-right: 25px !important;  /* 💽右侧留白 */
    min-height: 0px !important;  
    text-align: justify; 
}

/* --- Char (角色) 文本框 --- */
.mes[is_user="false"] .mes_text {
    padding-top: -50px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: -50px !important;/*💿同上*/
    padding-bottom: 0px !important; /* 💽底部留白 */
    padding-left: 15px !important;   /* 💽左侧留白 */
    padding-right: 25px !important; /* 💽右侧留白 */
    min-height: 0px !important;
    text-align: justify;
}


/*杂七杂八的东西*/
.mesIDDisplay, .mes_timer, .tokenCounterDisplay, .name_text, .timestamp {
    position: absolute !important;
    z-index: 9;
    width: auto !important;
    white-space: nowrap !important;
    pointer-events: none; 
}


/* 自定义图标 - 编辑按钮 (小铅笔) */
.fa-pencil::before,
.fa-pencil-alt::before {
  display: inline-block !important;
  width: 28px !important;
  height: 28px !important;
  background-image: url('https://iili.io/qFThKle.png') !important;
  background-size: contain !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  vertical-align: middle !important;
  opacity: 1 !important;
  content: '' !important;
  box-shadow: none !important;
  text-shadow: none !important;
  transition: none !important;
}

/* 自定义图标 - 菜单按钮 (省略号) */
.fa-ellipsis::before,
.fa-ellipsis-h::before {
  display: inline-block !important;
  width: 28px !important;
  height: 28px !important;
  background-image: url('https://iili.io/qFTjUjR.png') !important;
  background-size: contain !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  vertical-align: middle !important;
  opacity: 1 !important;
  content: '' !important;
  box-shadow: none !important;
  text-shadow: none !important;
  transition: none !important;
}

/* 收藏按钮 */
.mes_buttons .fa-star {
    border: 0 !important; 
    background: none !important; 
    box-shadow: none !important;
    display: inline-block; 
    width: 28px; 
    height: 28px; 
    position: relative;
    opacity: 1 !important; /* 确保透明度为1 */
}

/* 默认状态图标 */
.mes_buttons .fa-star::before {
  display: inline-block !important;
  width: 28px !important;
  height: 28px !important;
  background-image: url('https://iili.io/qFTwH67.png') !important;
  background-size: contain !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  vertical-align: middle !important;
  opacity: 1 !important;
  content: '' !important;
  box-shadow: none !important;
  text-shadow: none !important;
  transition: none !important;
}

/* 修复小铅笔/省略号*/
.mes_buttons, 
.mes_edit_buttons,
.mes_buttons *, 
.mes_edit_buttons *,
.mes_buttons div, 
.mes_edit_buttons button {
    text-shadow: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}


/* 底栏容器 */
#send_form {
    display: block !important; 
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    position: relative !important;
    z-index: 50 !important;
    background: transparent !important;
    border: none !important;
    padding: 8px 8px 10px 8px !important; 
    overflow: visible !important;
    height: auto !important; 
}

#send_form::before {
    content: "";
    position: absolute;
    top: -20px; left: 0; right: 0; bottom: 0;
    background-image: url('https://iili.io/qFTUUwF.png') !important;
    background-size: cover !important; 
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-color: rgba(13, 16, 21, 0) !important; 
    backdrop-filter: blur(0px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
