/*世界书界面*/
#world_popup {
    background-image: none !important; /* 强制移除背景图 */
    background-color: rgba(153, 153, 153, 0.1) !important; 
    backdrop-filter: blur(3px) !important; /* 背景模糊 */
    border: 1px solid rgba(153, 153, 153, 0.3) !important; /* 细微边框 */
    box-shadow: 0 10px 30px rgba(153, 153, 153, 0.5) !important; /* 柔和阴影 */
    border-radius: 8px !important; /* 窗口圆角 */
}


.wi-card-entry {
  border-radius: 0px !important; /* （可选)圆角数值 */
  padding: 20px;
